macro_rules! intrinsic_operation_unsafety {
    () => {
        # [doc = " Returns the unsafety of the given intrinsic."] fn intrinsic_operation_unsafety (tcx : TyCtxt < '_ > , intrinsic_id : LocalDefId) -> hir :: Safety { let is_in_list = match tcx . item_name (intrinsic_id) { sym :: abort | sym :: assert_inhabited | sym :: assert_zero_valid | sym :: assert_mem_uninitialized_valid | sym :: box_new | sym :: breakpoint | sym :: size_of | sym :: align_of | sym :: needs_drop | sym :: caller_location | sym :: add_with_overflow | sym :: sub_with_overflow | sym :: mul_with_overflow | sym :: carrying_mul_add | sym :: wrapping_add | sym :: wrapping_sub | sym :: wrapping_mul | sym :: saturating_add | sym :: saturating_sub | sym :: rotate_left | sym :: rotate_right | sym :: ctpop | sym :: ctlz | sym :: cttz | sym :: bswap | sym :: bitreverse | sym :: three_way_compare | sym :: discriminant_value | sym :: type_id | sym :: type_id_eq | sym :: select_unpredictable | sym :: cold_path | sym :: ptr_guaranteed_cmp | sym :: minnumf16 | sym :: minnumf32 | sym :: minnumf64 | sym :: minnumf128 | sym :: minimumf16 | sym :: minimumf32 | sym :: minimumf64 | sym :: minimumf128 | sym :: maxnumf16 | sym :: maxnumf32 | sym :: maxnumf64 | sym :: maxnumf128 | sym :: maximumf16 | sym :: maximumf32 | sym :: maximumf64 | sym :: maximumf128 | sym :: rustc_peek | sym :: type_name | sym :: forget | sym :: black_box | sym :: variant_count | sym :: is_val_statically_known | sym :: ptr_mask | sym :: aggregate_raw_ptr | sym :: ptr_metadata | sym :: ub_checks | sym :: contract_checks | sym :: contract_check_requires | sym :: contract_check_ensures | sym :: fadd_algebraic | sym :: fsub_algebraic | sym :: fmul_algebraic | sym :: fdiv_algebraic | sym :: frem_algebraic | sym :: round_ties_even_f16 | sym :: round_ties_even_f32 | sym :: round_ties_even_f64 | sym :: round_ties_even_f128 | sym :: autodiff | sym :: prefetch_read_data | sym :: prefetch_write_data | sym :: prefetch_read_instruction | sym :: prefetch_write_instruction | sym :: const_eval_select => hir :: Safety :: Safe , _ => hir :: Safety :: Unsafe , } ; if tcx . fn_sig (intrinsic_id) . skip_binder () . safety () != is_in_list { tcx . dcx () . struct_span_err (tcx . def_span (intrinsic_id) , DiagMessage :: from (format ! ("intrinsic safety mismatch between list of intrinsics within the compiler and core library intrinsics for intrinsic `{}`" , tcx . item_name (intrinsic_id)))) . emit () ; } is_in_list }
    };
}

intrinsic_operation_unsafety!()